def compute(vars):
    total = vars["v2"]
    if total == 0:
        return None

    ratio = vars["v1"] / total
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "restructuring_charges": vars["v1"],
            "total_charges": total,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
